using namespace sqlgen;
using namespace sqlgen::literals;

// Insert records into the EAS database.
// T is expected to be one of: Student, Course, Score, Major.
template <typename T>
void add_eas_records(const std::string& table_name,
                     const std::vector<T>& records) {
  if (records.empty()) {
    return;
  }

  // Only proceed if the provided table_name matches the type T.
  const std::string type_name = rfl::to_string(rfl::reflect<T>().name());
  if (table_name != type_name) {
    throw std::runtime_error("Table name does not match record type");
  }

  auto conn_res = sqlgen::sqlite::connect(db_path);
  conn_res.and_then([&](auto&& conn) {
    // sqlgen::write can insert a container of records in one go.
    sqlgen::write(conn, records);
    return sqlgen::result<void>{};
  }).value();
}

// Modify a single column of a record identified by primary key.
// record_id is passed as string for simplicity and will be bound as-is.
inline void modify_eas_records_by_id(const std::string& table_name,
                                     const std::string& record_id,
                                     const std::string& col_name,
                                     const std::string& new_value) {
  auto conn_res = sqlgen::sqlite::connect(db_path);

  conn_res.and_then([&](auto&& conn) {
    // Build a dynamic UPDATE statement:
    // UPDATE table_name SET col_name = ? WHERE <pk_column> = ?;
    using namespace sqlgen::dynamic;

    // Determine primary key column name based on the static schema.
    // This small helper maps table_name to its primary key column.
    auto get_pk_name = [](const std::string& tname) -> std::string {
      if (tname == "Student") return "SNo";
      if (tname == "Course")  return "CID";
      if (tname == "Score")   return "ScID";
      if (tname == "Major")   return "MID";
      throw std::runtime_error("Unknown table name: " + tname);
    };

    const auto pk_name = get_pk_name(table_name);

    Update upd;
    upd.table = Table{.name = table_name};
    upd.set.push_back(SetClause{
        .column = Column{.name = col_name},
        .value = Value{new_value}
    });

    // WHERE pk_name = record_id
    Condition cond;
    cond.left = Column{.name = pk_name};
    cond.op = Condition::Operator::EQ;
    cond.right = Value{record_id};
    upd.where = cond;

    // Execute the dynamic UPDATE.
    sqlgen::exec(conn, upd);
    return sqlgen::result<void>{};
  }).value();
}

// Delete a record by primary key value.
// record_id is passed as string for simplicity and will be bound as-is.
inline void delete_eas_records_by_id(const std::string& table_name,
                                     const std::string& record_id) {
  auto conn_res = sqlgen::sqlite::connect(db_path);

  conn_res.and_then([&](auto&& conn) {
    using namespace sqlgen::dynamic;

    auto get_pk_name = [](const std::string& tname) -> std::string {
      if (tname == "Student") return "SNo";
      if (tname == "Course")  return "CID";
      if (tname == "Score")   return "ScID";
      if (tname == "Major")   return "MID";
      throw std::runtime_error("Unknown table name: " + tname);
    };

    const auto pk_name = get_pk_name(table_name);

    Delete del;
    del.from = Table{.name = table_name};

    Condition cond;
    cond.left = Column{.name = pk_name};
    cond.op = Condition::Operator::EQ;
    cond.right = Value{record_id};
    del.where = cond;

    sqlgen::exec(conn, del);
    return sqlgen::result<void>{};
  }).value();
}
