```cpp
#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace batch_insert_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  float price;
  std::string category;
  int stock;
};

/**
 * Function: Perform efficient batch insertion of product data using a transaction.
 * 
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
  try {
    // Connect to SQLite database "test_db.sqlite"
    const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Drop Product table if it exists
    {
      const char* drop_sql = "DROP TABLE IF EXISTS Product;";
      if (sqlite3_exec(conn.native_handle(), drop_sql, nullptr, nullptr, nullptr) !=
          SQLITE_OK) {
        return false;
      }
    }

    // Create Product table
    {
      const char* create_sql =
          "CREATE TABLE Product ("
          "product_id INTEGER PRIMARY KEY,"
          "name VARCHAR(100) NOT NULL,"
          "price REAL NOT NULL,"
          "category VARCHAR(50) NOT NULL,"
          "stock INTEGER NOT NULL DEFAULT 0"
          ");";
      if (sqlite3_exec(conn.native_handle(), create_sql, nullptr, nullptr, nullptr) !=
          SQLITE_OK) {
        return false;
      }
    }

    // Begin transaction
    if (sqlite3_exec(conn.native_handle(), "BEGIN TRANSACTION;", nullptr, nullptr,
                     nullptr) != SQLITE_OK) {
      return false;
    }

    bool ok = true;

    // Perform batch insert using sqlgen::write inside the transaction
    for (const auto& product : products) {
      auto res = sqlgen::write(conn, product);
      if (!res.has_value()) {
        ok = false;
        break;
      }
    }

    if (ok) {
      // Commit transaction
      if (sqlite3_exec(conn.native_handle(), "COMMIT;", nullptr, nullptr,
                       nullptr) != SQLITE_OK) {
        return false;
      }
      return true;
    } else {
      // Rollback transaction on failure
      sqlite3_exec(conn.native_handle(), "ROLLBACK;", nullptr, nullptr, nullptr);
      return false;
    }
  } catch (...) {
    // In case of any unexpected exception, indicate failure
    return false;
  }
}

}  // namespace batch_insert_products
```

