```cpp
#pragma once

#include <optional>
#include <string>

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <sqlgen/delete_from.hpp>
#include <sqlgen/literals.hpp>

namespace delete_inactive_users {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
  std::optional<sqlgen::DateTime> last_login;
  std::string status = "active";
};

int delete_inactive_users() {
  // Connect to the SQLite database "test_db.sqlite"
  auto conn_res = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    // Connection failed; return non-zero to indicate error.
    return 1;
  }

  auto conn = conn_res.value();

  // Begin a transaction to ensure safety
  auto begin_res = conn->execute("BEGIN TRANSACTION;");
  if (!begin_res) {
    return 1;
  }

  // Delete users who have not logged in since 2025-01-01
  // Equivalent SQL:
  // DELETE FROM User WHERE last_login < DATE('2025-01-01');
  using namespace sqlgen::literals;

  const auto where_clause =
      "last_login"_field < sqlgen::DateTime{"2025-01-01 00:00:00"};

  auto delete_res =
      sqlgen::delete_from_impl<User>(sqlgen::Ref{conn}, where_clause);
  if (!delete_res) {
    // Rollback on failure
    conn->execute("ROLLBACK;");
    return 1;
  }

  // Commit the transaction
  auto commit_res = conn->execute("COMMIT;");
  if (!commit_res) {
    // Commit failed; return non-zero
    return 1;
  }

  // Return operation result of commit: 0 for success
  return 0;
}

} // namespace delete_inactive_users
```

