          class ConditionType>
auto inner_join(const QueryType& _query, const ConditionType& _on) {
  return join<_alias, transpilation::JoinType::inner_join>(_query, _on);
}

template <class TableType, rfl::internal::StringLiteral _alias,
          class ConditionType>
auto inner_join(const ConditionType& _on) {
  return join<_alias, transpilation::JoinType::inner_join>(
      transpilation::TableWrapper<TableType>{}, _on);
}

template <class ConditionType>
inline auto where(const ConditionType& _cond) {
  return Where<std::remove_cvref_t<ConditionType>>{.condition = _cond};
};

template <class... ColTypes>
auto group_by(const ColTypes&...) {
  return GroupBy<ColTypes...>{};
};

template <class ValueType, class... Args>
inline auto create_as(const SelectFrom<Args...>& _as) {
  return CreateAs<std::remove_cvref_t<ValueType>, Args...>{
      .what_ = transpilation::get_table_or_view<ValueType>(),
      .as_ = _as,
      .or_replace_ = false,
      .if_not_exists_ = false};
}

template <rfl::internal::StringLiteral _new_name>
auto as() const noexcept {
  using T = std::remove_cvref_t<decltype(*this)>;
  return transpilation::As<T, _new_name>{.val = *this};
}

template <class T>
friend auto operator>(const Operation& _o, const T& _t) {
  return make_condition(
      conditions::greater_than(_o, to_transpilation_type(_t)));
}

template <class T>
friend auto operator==(const Col&, const T& _t) {
  return transpilation::make_condition(transpilation::conditions::equal(
      transpilation::Col<_name, _alias>{},
      transpilation::to_transpilation_type(_t)));
}

