  sqlgen::PrimaryKey<int> enrollment_id;
  sqlgen::ForeignKey<int, Course, "course_id"> course_id;
  std::optional<float> grade;
};

struct CourseStats {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

struct CourseStatsView {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

/**
 * Function: Calculate enrollment statistics per course.
 * 
 * @return List of course statistics
 */
std::vector<CourseStats> query_course_enrollment_stats() {
  // Connect to the SQLite database "test_db.sqlite"
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Create Course and Enrollment tables if they do not exist
  sqlgen::create_table_if_not_exists<Course>(conn);
  sqlgen::create_table_if_not_exists<Enrollment>(conn);

  // Build and execute the query:
  // SELECT c.title,
  //        COUNT(e.enrollment_id) AS student_count,
  //        AVG(e.grade)           AS avg_grade
  // FROM Course c
  // LEFT JOIN Enrollment e ON c.course_id = e.course_id
  // GROUP BY c.course_id, c.title;
  auto q = sqlgen::select(
               &Course::title,
               sqlgen::count(&Enrollment::enrollment_id).as(&CourseStatsView::student_count),
               sqlgen::avg(&Enrollment::grade).as(&CourseStatsView::avg_grade))
               .from<Course>()
               .left_join<Enrollment>(
                   sqlgen::on(&Course::course_id, &Enrollment::course_id))
               .group_by(&Course::course_id, &Course::title);

  auto rows = sqlgen::fetch_all<CourseStatsView>(conn, q);

  std::vector<CourseStats> result;
  result.reserve(rows.size());

  for (const auto &row : rows) {
    CourseStats cs;
    cs.title = row.title;
    cs.student_count = row.student_count;
    cs.avg_grade = row.avg_grade;
    result.push_back(std::move(cs));
  }

  return result;
}

}  // namespace query_course_enrollment_stats
