    if (!res) return {};
  }
  {
    auto res = create_table_if_not_exists<Product>(conn);
    if (!res) return {};
  }
  {
    auto res = create_table_if_not_exists<Order>(conn);
    if (!res) return {};
  }
  {
    auto res = create_table_if_not_exists<OrderItem>(conn);
    if (!res) return {};
  }

  // Reference SQL:
  // SELECT p.name, o.order_date, oi.quantity
  // FROM Customer c
  // JOIN "Order" o ON c.customer_id = o.customer_id
  // JOIN OrderItem oi ON o.order_id = oi.order_id
  // JOIN Product p ON oi.product_id = p.product_id
  // WHERE c.customer_id = ?
  // ORDER BY o.order_date DESC;

  std::vector<PurchaseHistory> result;

  const char* sql =
      "SELECT p.name, o.order_date, oi.quantity "
      "FROM Customer c "
      "JOIN \"Order\" o ON c.customer_id = o.customer_id "
      "JOIN OrderItem oi ON o.order_id = oi.order_id "
      "JOIN Product p ON oi.product_id = p.product_id "
      "WHERE c.customer_id = ? "
      "ORDER BY o.order_date DESC;";

  auto stmt_res = conn.prepare(sql);
  if (!stmt_res) {
    return result;
  }
  auto stmt = std::move(stmt_res).value();

  // Bind the customer_id parameter
  auto bind_res = stmt.bind(1, customer_id);
  if (!bind_res) {
    return result;
  }

  while (true) {
    auto step_res = stmt.step();
    if (!step_res) {
      // Error
      result.clear();
      return result;
    }
    if (step_res.value() == sqlite::Statement::StepResult::Done) {
      break;
    }

    PurchaseHistory ph{};
    auto col0 = stmt.get<std::string>(0);
    auto col1 = stmt.get<std::string>(1);
    auto col2 = stmt.get<int>(2);

    if (!col0 || !col1 || !col2) {
      continue;
