    ph.product_name = col0.value();
    ph.order_date = sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S">{col1.value()};
    ph.quantity = col2.value();

    result.push_back(std::move(ph));
  }

  return result;
}

