#pragma once

#include <ranges>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <stdexcept>

namespace query_daily_traffic_metrics {

struct PageVisit {
  sqlgen::PrimaryKey<int> visit_id;
  std::string url;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> visit_time;
};

struct DailyTraffic {
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

struct DailyTrafficView {
  static constexpr const char* tablename = "DailyTrafficView";
  static constexpr bool is_view = true;
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

/**
 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  // Connect to SQLite database "test_db.sqlite"
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    throw std::runtime_error(
        std::string("Failed to connect to database: ") +
        conn_result.error().what());
  }
  auto conn = *conn_result;

  // Create a view that matches the desired aggregation query
  {
    const char* create_view_sql =
        "CREATE VIEW IF NOT EXISTS DailyTrafficView AS "
        "SELECT "
        "  strftime('%Y-%m-%d', visit_time) AS visit_date, "
        "  COUNT(*) AS total_visits, "
        "  COUNT(DISTINCT url) AS unique_pages "
        "FROM PageVisit "
        "GROUP BY visit_date "
        "ORDER BY visit_date;";
    auto exec_res = conn->execute(create_view_sql);
    if (!exec_res) {
      throw std::runtime_error(
          std::string("Failed to create view DailyTrafficView: ") +
          exec_res.error().what());
    }
  }

  // Build a SELECT * FROM DailyTrafficView
  auto select_stmt = sqlgen::dynamic::SelectFrom::from<DailyTrafficView>();

  // Read data into vector<DailyTrafficView>
  auto read_res =
      conn->template read<std::vector<DailyTrafficView>>(select_stmt);
  if (!read_res) {
    throw std::runtime_error(
        std::string("Failed to query DailyTrafficView: ") +
        read_res.error().what());
  }

  const auto& view_rows = *read_res;
  std::vector<DailyTraffic> result;
  result.reserve(view_rows.size());

  for (const auto& row : view_rows) {
    result.push_back(DailyTraffic{
        row.visit_date,
        row.total_visits,
        row.unique_pages,
    });
  }

  return result;
}

}  // namespace query_daily_traffic_metrics
