namespace query_employee_hierarchy {

struct Employee {
  sqlgen::PrimaryKey<int> emp_id;
  std::string name;
  std::optional<int> manager_id;
};

struct EmployeeManager {
  std::string employee;
  std::optional<std::string> manager;
};

std::vector<EmployeeManager> query_employee_hierarchy() {
  using namespace sqlgen;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    // Propagate the error as an exception for simplicity
    throw std::runtime_error(conn_result.error());
  }
  auto conn = conn_result.value();

  // Build the self-join query:
  //
  // SELECT e1.name AS employee, e2.name AS manager
  // FROM Employee e1
  // LEFT JOIN Employee e2 ON e1.manager_id = e2.emp_id;
  //
  // with the help of sqlgen's dynamic query builder.
  using dynamic::SelectFrom;
  using dynamic::Table;
  using dynamic::Column;
  using dynamic::Join;
  using dynamic::JoinType;

  // Define the two table references (aliases)
  Table e1{"Employee", "e1"};
  Table e2{"Employee", "e2"};

  // Define the columns we need for the join and the select list
  Column e1_manager_id{e1, "manager_id"};
  Column e1_name{e1, "name"};
  Column e2_emp_id{e2, "emp_id"};
  Column e2_name{e2, "name"};

  // Build the SELECT statement
  SelectFrom query;
  query.from = e1;

  // LEFT JOIN Employee e2 ON e1.manager_id = e2.emp_id
  query.joins.push_back(
      Join{.type = JoinType::Left, .table = e2, .on = e1_manager_id == e2_emp_id});

  // SELECT e1.name AS employee, e2.name AS manager
  query.columns.push_back({e1_name, "employee"});
  query.columns.push_back({e2_name, "manager"});

  // Execute the query
  auto iter_result = conn.and_then(read(query));
  if (!iter_result) {
    throw std::runtime_error(iter_result.error());
  }

  auto iter = std::move(iter_result.value());
  std::vector<EmployeeManager> results;

  // Iterate over the rows and populate EmployeeManager structs
  while (iter->next()) {
    EmployeeManager em{};

    // Column 0: employee (TEXT, NOT NULL)
    em.employee = iter->get<std::string>(0).value();

    // Column 1: manager (TEXT, may be NULL)
    auto mgr = iter->get<std::optional<std::string>>(1);
    if (mgr) {
      em.manager = *mgr;
    } else {
      em.manager.reset();
    }

    results.push_back(std::move(em));
  }

  return results;
}

}  // namespace query_employee_hierarchy

