```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace query_high_value_orders {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  int customer_id;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

struct OrderView {
  static constexpr const char* tablename = "HighValueOrderView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string name;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

std::vector<OrderView> query_high_value_orders() {
  // Open SQLite connection to the given database file.
  sqlgen::sqlite::Connection conn("test_db.sqlite");

  // Register the table mappings so sqlgen knows the schema.
  auto db = sqlgen::make_database<Customer, Order, OrderView>();

  // Build a SELECT query equivalent to:
  //
  // SELECT o.order_id, c.name, o.total_amount, o.order_date
  // FROM "Order" o
  // INNER JOIN Customer c ON o.customer_id = c.customer_id
  // WHERE o.total_amount > 1000
  // ORDER BY o.total_amount DESC;
  //
  // and map the result into OrderView.
  auto query =
      db.select<OrderView>()
          .from<Order>()
          .inner_join<Customer>()
          .on(&Order::customer_id == &Customer::customer_id)
          .where(&Order::total_amount > 1000.0)
          .order_by_desc(&Order::total_amount);

  // Execute the query and return the results as a vector<OrderView>.
  return conn.execute(query).value();
}

}  // namespace query_high_value_orders
```

