namespace query_product_sales_report {

using namespace sqlgen::literals;

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string category;
};

struct Sale {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct CategoryReport {
  std::string category;
  int total_qty;
  double total_amt;
};

struct ProductSalesReport {
  static constexpr const char* tablename = "ProductSalesReport";
  static constexpr bool is_view = true;
  std::string category;
  int total_qty;
  double total_amt;
};

std::vector<CategoryReport> query_product_sales_report() {
  // Connect to SQLite database "test_db.sqlite"
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build and execute:
  // SELECT p.category AS category,
  //        SUM(s.quantity) AS total_qty,
  //        SUM(s.amount)   AS total_amt
  // FROM Product p
  // INNER JOIN Sale s ON p.product_id = s.product_id
  // GROUP BY p.category
  // HAVING total_amt > 5000;
  const auto rows =
      sqlgen::select_from<ProductSalesReport>(
          {
              "Product" * "p",
              "Sale" * "s",
          },
          {
              "p.category AS category",
              "SUM(s.quantity) AS total_qty",
              "SUM(s.amount) AS total_amt",
          })
          .join("p.product_id = s.product_id")
          .group_by({"p.category"})
          .having("total_amt > 5000")
          .read(conn)
          .value();

  std::vector<CategoryReport> result;
  result.reserve(rows.size());

  for (const auto& r : rows) {
    result.push_back(CategoryReport{
        .category = r.category,
        .total_qty = r.total_qty,
        .total_amt = r.total_amt,
    });
  }

  return result;
}

}  // namespace query_product_sales_report
