/**
 * Function: Perform schema migration to add new columns.
 * 
 * @return true if migration succeeds, false otherwise
 */
bool migration_add_column() {
  try {
    // Connect to the SQLite database
    const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Create the "before" schema table if it does not exist so that migration
    // can be run safely in tests / repeated runs.
    // This uses sqlgen to ensure the table exists with the expected base schema.
    {
      // The library will derive the table name from the struct name "User".
