```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>
#include <string>

namespace soft_delete_records {

struct Document {
  sqlgen::PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<sqlgen::DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
  if (ids.empty()) {
    return true;  // nothing to do, treat as success
  }

  // Connect to the SQLite database "test_db.sqlite"
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }
  auto conn = std::move(conn_result.value());

  // We will perform the updates inside a transaction
  auto tx_result = conn.transaction();
  if (!tx_result) {
    return false;
  }
  auto tx = std::move(tx_result.value());

  // For each id, perform an update using sqlgen's fluent API
  using namespace sqlgen;
  using namespace sqlgen::literals;

  for (const auto id : ids) {
    // Build the update statement:
    // UPDATE Document
    // SET is_deleted = 1, deleted_at = CURRENT_TIMESTAMP
    // WHERE doc_id = ?
    const auto upd =
        update<Document>("is_deleted"_c.set(1),
                         "deleted_at"_c.set(sqlgen::current_timestamp())) |
        where("doc_id"_c == id);

    auto res = tx.and_then(upd);
    if (!res) {
      // Rollback on first failure
      tx.rollback();
      return false;
    }
  }

  // Commit the transaction
  auto commit_res = tx.commit();
  if (!commit_res) {
    return false;
  }

  return true;
}

}  // namespace soft_delete_records
```

