```cpp
#pragma once

#include <stdexcept>

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace transaction_transfer_funds {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  if (amount <= 0.0) {
    return false;
  }

  // Open SQLite connection to the required database.
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  try {
    // Start transaction.
    conn.execute("BEGIN TRANSACTION;");

    // 1) Load sender account and verify sufficient funds.
    auto maybe_from =
        conn(read<Account> |
             where(field<&Account::account_id>() == from_account_id));

    if (!maybe_from) {
      conn.execute("ROLLBACK;");
      return false;  // Sender does not exist.
    }

    Account from_acc = *maybe_from;
    if (from_acc.balance < amount) {
      conn.execute("ROLLBACK;");
      return false;  // Insufficient funds.
    }

    // 2) Load receiver account to ensure it exists.
    auto maybe_to =
        conn(read<Account> |
             where(field<&Account::account_id>() == to_account_id));

    if (!maybe_to) {
      conn.execute("ROLLBACK;");
      return false;  // Receiver does not exist.
    }

    // 3) Deduct from sender.
    const auto update_from =
        update<Account> |
        set(field<&Account::balance>() = field<&Account::balance>() - amount) |
        where(field<&Account::account_id>() == from_account_id);

    const auto rows_from = conn(update_from);
    if (rows_from != 1) {
      conn.execute("ROLLBACK;");
      return false;
    }

    // 4) Credit receiver.
    const auto update_to =
        update<Account> |
        set(field<&Account::balance>() = field<&Account::balance>() + amount) |
        where(field<&Account::account_id>() == to_account_id);

    const auto rows_to = conn(update_to);
    if (rows_to != 1) {
      conn.execute("ROLLBACK;");
      return false;
    }

    // 5) Commit transaction.
    conn.execute("COMMIT;");
    return true;
  } catch (const std::exception&) {
    // Any failure should roll back the transaction.
    try {
      conn.execute("ROLLBACK;");
    } catch (...) {
      // Suppress rollback exceptions.
    }
    return false;
  }
}

}  // namespace transaction_transfer_funds
```

