int update_order_status() {
  // Connect to the SQLite database "test_db.sqlite"
  auto conn_result = sqlgen::sqlite::Connection::open("test_db.sqlite");
  if (!conn_result) {
    // Opening the connection failed; propagate as an exception
    throw std::runtime_error(conn_result.error().what());
  }
  auto conn = std::move(conn_result).value();

  int total_rows_affected = 0;

  // 1) Expire 'pending' orders older than 7 days
  {
    // Using SQLite's date function: order_date < DATE('now', '-7 days')
    const std::string sql_expire_pending =
        "UPDATE \"Order\" "
        "SET status = 'expired' "
        "WHERE status = 'pending' "
        "AND order_date < DATE('now', '-7 days');";

    auto res = conn.execute(sql_expire_pending);
    if (!res) {
      throw std::runtime_error(res.error().what());
    }

    // sqlite3_changes() is wrapped by Connection::changes()
    auto changes_res = conn.changes();
    if (!changes_res) {
      throw std::runtime_error(changes_res.error().what());
    }
    total_rows_affected += changes_res.value();
  }

  // 2) Simulate delivery confirmations:
  //    Update 'shipped' orders to 'delivered'
  {
    const std::string sql_ship_to_delivered =
        "UPDATE \"Order\" "
        "SET status = 'delivered' "
        "WHERE status = 'shipped';";

    auto res = conn.execute(sql_ship_to_delivered);
    if (!res) {
      throw std::runtime_error(res.error().what());
    }

    auto changes_res = conn.changes();
    if (!changes_res) {
      throw std::runtime_error(changes_res.error().what());
    }
    total_rows_affected += changes_res.value();
  }

  // Return the total number of rows affected by both updates
  return total_rows_affected;
}

