namespace schema_create_view_sales_summary {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  double price;
  int stock;
};

struct Sale {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> sale_id;
  int product_id;
  int quantity;
  double amount;
};

struct SalesSummary {
  // Optional: explicitly set the view name, otherwise sqlgen will derive it.
  static constexpr const char* viewname = "SalesSummary";
  static constexpr bool is_view = true;

  std::string product_name;
  int total_quantity;
  double total_revenue;
};

/**
 * Function: Create a view SalesSummary that aggregates sales by product.
 * 
 * @return true if view creation succeeds, false otherwise
 */
bool create_view_sales_summary() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // 1. Connect to SQLite database "test_db.sqlite"
  auto conn_result = sqlite::Connection::open("test_db.sqlite");
  if (!conn_result) {
    std::cerr << "Failed to open database: " << conn_result.error().what() << std::endl;
    return false;
  }
  auto conn = std::move(*conn_result);

  // 2. Manually drop existing view if it exists (SQLite lacks DROP VIEW IF EXISTS until newer versions;
  //    we do it manually for portability).
  {
    auto drop_result = conn->execute("DROP VIEW IF EXISTS SalesSummary;");
    if (!drop_result) {
      std::cerr << "Failed to drop existing view SalesSummary: "
                << drop_result.error().what() << std::endl;
      // Not fatal; continue trying to create the new view.
    }
  }

  // 3. Construct the SELECT query for the view:
  //
  //   SELECT p.name AS product_name,
  //          SUM(s.quantity) AS total_quantity,
  //          SUM(s.amount)   AS total_revenue
  //   FROM Sale s
  //   JOIN Product p ON s.product_id = p.product_id
  //   GROUP BY p.name;
  //
  // Note: We build this using sqlgen APIs and then wrap it in a CREATE VIEW statement.

  auto select_sql = std::string{
      "SELECT p.name AS product_name, "
      "SUM(s.quantity) AS total_quantity, "
      "SUM(s.amount) AS total_revenue "
      "FROM Sale s "
      "JOIN Product p ON s.product_id = p.product_id "
      "GROUP BY p.name"};

  // 4. Build the CREATE VIEW statement. sqlgen has create_as, but for a custom aggregate
  //    it's simpler and clearer to emit SQL directly here.
  auto create_view_sql =
      std::string{"CREATE VIEW SalesSummary AS "} + select_sql + ";";

  // 5. Execute the CREATE VIEW statement.
  auto create_result = conn->execute(create_view_sql);
  if (!create_result) {
    std::cerr << "Failed to create view SalesSummary: "
              << create_result.error().what() << std::endl;
    return false;
  }

  return true;
}

}  // namespace schema_create_view_sales_summary

