#include <vector>
#include <optional>

namespace right_join_departments_projects {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string name;
};

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  int department_id;
  std::string name;
};

struct DepProj {
  std::optional<std::string> department_name;
  std::string project_name;
};

/**
 * description: right_join_departments_projects.
 * This function demonstrates how to perform a right join between departments and projects using sqlgen read API.
 * It returns a vector of DepProj structs, where each struct contains the department name (if available) and the project name.
 * Returns: std::vector<DepProj>.
 */
std::vector<DepProj> right_join_departments_projects() {
  namespace sg = sqlgen;

  // Connect to the SQLite database "test_db.sqlite"
  auto conn = sg::sqlite::connect("test_db.sqlite");

  // NOTE:
  // SQLite does not support RIGHT JOIN directly. To include all departments
  // (and any projects they may have), we use a LEFT JOIN from Department to
  // Project. This is logically equivalent to a RIGHT JOIN from Project to
  // Department, but matches the requirement of "include departments without
  // projects".
  //
  // SQL equivalent:
  //   SELECT d.name AS department_name, p.name AS project_name
  //   FROM Department d
  //   LEFT JOIN Project p ON d.department_id = p.department_id;

  using D = Department;
  using P = Project;

  std::vector<DepProj> results;

  sg::read<
      // result type
      DepProj,
      // driver / connection
      sg::sqlite::driver
  >(
      conn,
      // select: map columns to DepProj fields
      sg::select(
          sg::col<&D::name>().as<&DepProj::department_name>(),
          sg::col<&P::name>().as<&DepProj::project_name>()
      ),
      // from Department
      sg::from<D>(),
      // LEFT JOIN Project ON d.department_id = p.department_id
      sg::left_join<P>(
          sg::on(
              sg::col<&D::department_id>(),
              sg::col<&P::department_id>()
          )
      ),
      // output iterator
      std::back_inserter(results)
  );

  return results;
}

}  // namespace right_join_departments_projects
