#pragma once

#include <cassert>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace generate_sql_dry_run {

struct A {
  sqlgen::PrimaryKey<int> id;
  std::string name;
};

struct B {
  sqlgen::PrimaryKey<int> id;
  int a_id;
  double score;
};

/**
 * This function demonstrates how to build a conditional SQL query.
 * It joins tables A and B, filtering for records where score > 10 and name contains 'x'.
 * Returns: std::string.
 */
std::string generate_sql_dry_run() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database (used here only to configure the dialect).
  const auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  // In a real application you'd handle errors; for this demo we assume success.
  assert(conn_result.has_value());
  const auto conn = conn_result.value();

  // Build a complex query:
  //   SELECT ...
  //   FROM A
  //   JOIN B ON A.id = B.a_id
  //   WHERE B.score > 10 AND A.name LIKE '%x%'
  //   ORDER BY B.score DESC
  //   LIMIT 5
  //
  // We use a std::vector of a simple struct as the result type to align with
  // sqlgen's read<> interface, although we only care about the generated SQL.
  struct ResultRow {
    int a_id;
    std::string a_name;
    int b_id;
    int b_a_id;
    double b_score;
  };

  const auto query =
      sqlgen::read<std::vector<ResultRow>> |
      join<B>(on("id"_c == "a_id"_c)) |
      where("score"_c > 10.0 and "name"_c.like("%x%")) |
      order_by(desc("score"_c)) |
      limit(5);

  // Generate SQL for SQLite without executing (dry run).
  const std::string sql = to_sql(query, conn);

  // Verify generated SQL string contains expected clauses.
  // These checks are defensive; they will fail in debug builds if sqlgen
  // changes in an incompatible way.
  assert(sql.find("JOIN") != std::string::npos);
  assert(sql.find("WHERE") != std::string::npos);
  assert(sql.find("ORDER BY") != std::string::npos);
  assert(sql.find("LIMIT") != std::string::npos);
  assert(sql.find("score") != std::string::npos);
  assert(sql.find("name") != std::string::npos);

  // For debugging purposes, the caller can print this SQL string.
  return sql;
}

}  // namespace generate_sql_dry_run
