```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>
#include <string>
#include <cmath>

namespace analyze_temporal_data {

struct Event {
  sqlgen::PrimaryKey<int> event_id;
  std::string event_name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  std::optional<sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S">> end_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct TemporalAnalysis {
  int event_id;
  std::string event_name;
  int start_day;
  int start_month;
  int start_year;
  int start_hour;
  int start_minute;
  int start_second;
  int start_weekday;
  int64_t start_epoch;
  std::optional<double> duration_days;
};

/**
 * @brief Analyze temporal data for a collection of events.
 *
 * Inserts the provided events into a temporary SQLite table, runs a query
 * to extract date/time parts and compute duration, and returns the results
 * as a vector of TemporalAnalysis.
 *
 * @param events Vector of Event records to analyze.
 * @return std::vector<TemporalAnalysis> Analysis results for each event that has an end_time.
 */
std::vector<TemporalAnalysis> analyze_temporal_data(const std::vector<Event>& events) {
  std::vector<TemporalAnalysis> results;

  // If there is nothing to analyze, just return an empty result.
  if (events.empty()) {
    return results;
  }

  // Connect to the SQLite database "test_db.sqlite".
  // The repository examples show connecting this way and then using sqlgen::write/read.
  const auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    // In a real system you might throw or propagate the error.
    // Here we just return an empty result on failure.
    return results;
  }

  auto conn = *conn_result;

  // Ensure the Event table exists in the database. In most real-world scenarios,
  // this would already exist; here we create it in case it doesn't.
  //
  // We rely on sqlgen's reflection capabilities to generate a suitable CREATE TABLE
  // statement from the Event struct definition.
  auto create_table_result = sqlgen::create_table<Event>(conn);
  if (!create_table_result) {
    return results;
  }

  // Insert the provided events into the Event table.
  // According to the reference snippets, `sqlgen::write(conn, object_or_range)`
  // will insert the data.
  auto insert_result = sqlgen::write(conn, events);
  if (!insert_result) {
    return results;
  }

  // Now run the temporal analysis query using SQLite's date/time functions.
  //
  // SQLite does not support DAY(), MONTH(), YEAR(), HOUR(), MINUTE(), SECOND(),
  // WEEKDAY(), UNIXEPOCH(), or DAYS_BETWEEN() as in the pseudo-SQL reference,
  // so we map them to their SQLite equivalents:
  //
  //   DAY(t)          -> CAST(STRFTIME('%d', t) AS INTEGER)
  //   MONTH(t)        -> CAST(STRFTIME('%m', t) AS INTEGER)
  //   YEAR(t)         -> CAST(STRFTIME('%Y', t) AS INTEGER)
  //   HOUR(t)         -> CAST(STRFTIME('%H', t) AS INTEGER)
  //   MINUTE(t)       -> CAST(STRFTIME('%M', t) AS INTEGER)
  //   SECOND(t)       -> CAST(STRFTIME('%S', t) AS INTEGER)
  //   WEEKDAY(t)      -> CAST(STRFTIME('%w', t) AS INTEGER)   -- 0=Sunday .. 6=Saturday
  //   UNIXEPOCH(t)    -> CAST(STRFTIME('%s', t) AS INTEGER)
  //   DAYS_BETWEEN(a,b)
  //                    -> (JULIANDAY(b) - JULIANDAY(a))
  //
  // We only report rows where end_time IS NOT NULL, as requested.
  const char* analysis_sql =
      "SELECT "
      "  event_id, "
      "  event_name, "
      "  CAST(STRFTIME('%d', start_time) AS INTEGER) AS start_day, "
      "  CAST(STRFTIME('%m', start_time) AS INTEGER) AS start_month, "
      "  CAST(STRFTIME('%Y', start_time) AS INTEGER) AS start_year, "
      "  CAST(STRFTIME('%H', start_time) AS INTEGER) AS start_hour, "
      "  CAST(STRFTIME('%M', start_time) AS INTEGER) AS start_minute, "
      "  CAST(STRFTIME('%S', start_time) AS INTEGER) AS start_second, "
      "  CAST(STRFTIME('%w', start_time) AS INTEGER) AS start_weekday, "
      "  CAST(STRFTIME('%s', start_time) AS INTEGER) AS start_epoch, "
      "  (JULIANDAY(end_time) - JULIANDAY(start_time)) AS duration_days "
      "FROM Event "
      "WHERE end_time IS NOT NULL;";

  auto stmt_result = conn->prepare(analysis_sql);
  if (!stmt_result) {
    return results;
  }

  auto stmt = *stmt_result;

  while (true) {
    auto step_result = stmt->step();
    if (!step_result) {
      // Error during stepping; stop and return what we have.
      break;
    }

    if (*step_result == sqlgen::sqlite::Statement::StepResult::Done) {
      // No more rows.
      break;
    }

    // Extract columns from the current row.
    TemporalAnalysis ta{};
    ta.event_id      = stmt->column_int(0);
    ta.event_name    = stmt->column_text(1);
    ta.start_day     = stmt->column_int(2);
    ta.start_month   = stmt->column_int(3);
    ta.start_year    = stmt->column_int(4);
    ta.start_hour    = stmt->column_int(5);
    ta.start_minute  = stmt->column_int(6);
    ta.start_second  = stmt->column_int(7);
    ta.start_weekday = stmt->column_int(8);
    ta.start_epoch   = static_cast<int64_t>(stmt->column_int64(9));

    // duration_days may be NULL if for some reason the calculation fails,
    // but given the WHERE end_time IS NOT NULL, we should normally get a value.
    if (stmt->column_type(10) == sqlgen::sqlite::ColumnType::Null) {
      ta.duration_days = std::nullopt;
    } else {
      double d = stmt->column_double(10);
      ta.duration_days = d;
    }

    results.push_back(std::move(ta));
  }

  return results;
}

}  // namespace analyze_temporal_data
