```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace limit_recent_events {

struct Event {
  sqlgen::PrimaryKey<int> event_id;
  std::string name;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

/**
 * description: limit_recent_events.
 * This function demonstrates how to limit the number of recent events returned.
 * It orders the events by created_at in descending order and returns the top n events.
 * Returns: std::vector<Event>.
 */
std::vector<Event> limit_recent_events(size_t n = 10) {
  // Connect to the SQLite database "test_db.sqlite"
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    // If the connection fails, return an empty vector.
    return {};
  }
  auto conn = *conn_result;

  // Build a read query:
  // - No WHERE clause (sqlgen::where())
  // - ORDER BY created_at DESC
  // - LIMIT n
  using sqlgen::order_by;
  using sqlgen::desc;
  using sqlgen::limit;
  using sqlgen::where;

  // Note: read_impl signature uses template parameters:
  //   ContainerType, WhereType, OrderByType, LimitType, Connection
  // We explicitly pass the OrderBy type as order_by<...> and
  // provide a dummy instance for the function call.
  using OrderByType = decltype(order_by(desc(&Event::created_at)));

  auto result = sqlgen::read_impl<std::vector<Event>, decltype(where(true)),
                                  OrderByType, decltype(limit(n))>(
      conn,
      where(true),                      // no filtering, select all
      limit(n)                          // limit to n rows
  );

  if (!result) {
    // On read failure, return an empty vector.
    return {};
  }

  // The sqlgen::read_impl already respects the order_by in the query
  // because OrderByType is part of the SelectFrom translation.
  return *result;
}

}  // namespace limit_recent_events
```

