```cpp
#pragma once

#include <optional>
#include <stdexcept>
#include <string>

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace read_single_record_by_id {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
  std::string email;
};

/**
 * description: read_single_record_by_id.
 * This function demonstrates how to read a single record by id using sqlgen read API.
 * It returns the matched row from the Customer table.
 * Returns: Customer.
 */
Customer read_single_record_by_id(int id) {
  using namespace sqlgen;
  using sqlite::Connection;

  // Open SQLite connection to the given database file.
  Connection conn{"test_db.sqlite"};

  // Define table metadata for Customer.
  constexpr auto customer_table =
      Table<Customer>("Customer",
                      Column<&Customer::customer_id>("customer_id"),
                      Column<&Customer::name>("name"),
                      Column<&Customer::email>("email"));

  // Build a SELECT ... WHERE customer_id = :id query.
  auto query = select_from(customer_table)
                   .where(customer_table.column<&Customer::customer_id>() ==
                          id);

  // Execute the read operation.
  auto result = conn.read<std::vector<Customer>>(query);

  if (!result) {
    throw std::runtime_error(
        "Failed to read from Customer table: " + result.error());
  }

  auto& rows = result.value();

  if (rows.empty()) {
    throw std::runtime_error("No Customer found with the given id");
  }

  // Return the first (and presumably only) matching row.
  return rows.front();
}

}  // namespace read_single_record_by_id
