#include <vector>

namespace inventory_bulk_write_and_read {

struct Inventory {
  sqlgen::PrimaryKey<int> item_id;
  std::string name;
  int quantity;
  std::string location;
};

/**
 * description: inventory_bulk_write_and_read.
 * This function demonstrates how to perform bulk write and read operations on an inventory table.
 * It first drops and recreates the table, then writes the given items to the table.
 * Finally, it reads back the items with quantity > 50, orders them by quantity in descending order,
 * and returns true if at least one item is found.
 * Returns: bool.
 */
bool inventory_bulk_write_and_read(const std::vector<Inventory>& items) {
  using namespace sqlgen::literals;

  // Connect to SQLite database "test_db.sqlite"
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Drop table if it exists and recreate it using the Inventory struct
  {
    const auto drop_sql =
        "DROP TABLE IF EXISTS Inventory;";
    conn->exec(drop_sql);

    // Create table for Inventory struct (sqlgen will generate the schema)
    sqlgen::create_table_if_not_exists<Inventory>(conn);
  }

  // Bulk write the batch of inventory items
  if (!items.empty()) {
    sqlgen::write(conn, items);
  }

  // Read records where quantity > 50 ordered by quantity DESC
  // Equivalent to:
  // SELECT item_id, name, quantity, location FROM Inventory
  // WHERE quantity > 50 ORDER BY quantity DESC;
  const auto threshold = 50;

  // Build the select query using sqlgen
  const auto result =
      sqlgen::read<std::vector<Inventory>>(
          conn,
          sqlgen::select_from<Inventory>()
              .where("quantity"_c > threshold)
              .order_by("quantity"_c, sqlgen::order::desc));

  if (!result) {
    // In case of failure, treat as no items found
    return false;
  }

  const auto &filtered_items = result.value();
  return !filtered_items.empty();
}

}  // namespace inventory_bulk_write_and_read
