```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool.
 */
bool cascade_delete_demo() {
  using namespace sqlgen;

  // Open / connect to SQLite database
  sqlgen::sqlite::Database db{"test_db.sqlite"};

  // Ensure foreign key support is enabled
  db.execute("PRAGMA foreign_keys = ON;");

  // Drop existing tables if they exist, to have a clean slate
  db.execute("DROP TABLE IF EXISTS Child;");
  db.execute("DROP TABLE IF EXISTS Parent;");

  // Create tables using sqlgen helpers
  db.create_table<Parent>();
  db.create_table<Child>();

  // Insert one parent
  Parent p{.parent_id = 1, .name = "Parent1"};
  db.insert(p);

  // Insert two children referencing that parent
  Child c1{.child_id = 1, .parent_id = 1, .note = "child 1"};
  Child c2{.child_id = 2, .parent_id = 1, .note = "child 2"};
  db.insert(c1);
  db.insert(c2);

  // Delete the parent; with ON DELETE CASCADE, children should be deleted
  db.remove<Parent>(p);

  // Check whether any child rows still exist for parent_id = 1
  auto remaining_children =
      db.select_where<Child>(sqlgen::field<&Child::parent_id>() == 1);

  // If cascade worked, no children should remain
  return remaining_children.empty();
}

}  // namespace cascade_delete_demo
```

