std::vector<Result> column_is_null_checks() {
  // Connect to the SQLite database "test_db.sqlite"
  const auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Read all Profile rows from the database
  const auto profiles_res =
      sqlgen::read<std::vector<Profile>>(conn);

  if (!profiles_res) {
    return {};
  }

  const auto& profiles = profiles_res.value();

  // Filter rows with missing fields (bio or avatar_url is NULL)
  std::vector<Result> results;
  results.reserve(profiles.size());

  for (const auto& p : profiles) {
    if (!p.bio.has_value() || !p.avatar_url.has_value()) {
      results.push_back(Result{
          .profile_id = p.profile_id.value,
          .display_name = p.display_name,
      });
    }
  }

  return results;
}

}  // namespace column_is_null_checks
