namespace update_set_operations {

TEST(sqlite, update_set_operations) {
  using namespace sqlgen;
  auto conn = sqlite::connect("test_db.sqlite").value();
  drop<Account>(conn);
  create_table<Account>(conn);
  insert(conn, std::vector<Account>{{1, 0.0, "inactive"}});

  ASSERT_TRUE(update_set_operations());
  auto rows = sqlgen::read<std::vector<Account>>(conn).value();
  ASSERT_EQ(rows.size(), 1);
}

}  // namespace update_set_operations

