                            transpilation::Col<_other_name, _other_alias>>{
      .to = transpilation::Col<_other_name, _other_alias>{}};
}

auto set(const char* _to) const noexcept {
    return transpilation::Set<transpilation::Col<_name, _alias>, std::string>{
        .to = _to};
  }

