```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * This function demonstrates how to use set operations in update statements using sqlgen write API.
 * It returns true if the update operations are successful, and false otherwise.
 * Returns: bool.
 */
bool update_set_operations() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // 1. Connect to SQLite database "test_db.sqlite"
  const auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) {
    return false;
  }
  auto conn = conn_res.value();

  // 2. Create Account table (drop first to ensure a clean slate)
  auto pipeline =
      drop<Account> | if_exists |  // ignore error if table does not exist
      create_table<Account>;

  if (!conn->execute(conn->to_sql(pipeline))) {
    return false;
  }

  // 3. Insert some sample data
  std::vector<Account> accounts{
      Account{.account_id = 1, .balance = 100.0, .status = "active"},
      Account{.account_id = 2, .balance = 200.0, .status = "inactive"},
      Account{.account_id = 3, .balance = 300.0, .status = "active"},
  };

  if (!write(conn, accounts)) {
    return false;
  }

  // 4. Update balances and statuses using set(...)

  // Example 1: Increase balance of account_id = 1 and set status to "premium"
  {
    auto res = update<Account>(
        conn,
        set("balance"_c = 150.0, "status"_c = "premium"),
        where("account_id"_c == 1));
    if (!res) {
      return false;
    }
  }

  // Example 2: Deactivate accounts with balance < 250.0
  {
    auto res = update<Account>(
        conn,
        set("status"_c = "inactive"),
        where("balance"_c < 250.0));
    if (!res) {
      return false;
    }
  }

  // 5. Verify changes persisted
  const auto read_res = read<std::vector<Account>>(conn);
  if (!read_res) {
    return false;
  }
  const auto& stored_accounts = read_res.value();

  // We expect exactly 3 accounts
  if (stored_accounts.size() != 3) {
    return false;
  }

  // Helper lambda to find an account by id
  auto find_account = [&](int id) -> const Account* {
    for (const auto& acc : stored_accounts) {
      if (acc.account_id == id) {
        return &acc;
      }
    }
    return nullptr;
  };

  const auto* acc1 = find_account(1);
  const auto* acc2 = find_account(2);
  const auto* acc3 = find_account(3);

  if (!acc1 || !acc2 || !acc3) {
    return false;
  }

  // After updates:
  // - account 1: balance = 150.0, status was set to "premium",
  //   then deactivation rule (balance < 250) sets status to "inactive".
  // - account 2: balance = 200.0, initially "inactive", remains "inactive".
  // - account 3: balance = 300.0, status remains "active".
  const bool acc1_ok =
      acc1->balance == 150.0 && acc1->status == "inactive";
  const bool acc2_ok =
      acc2->balance == 200.0 && acc2->status == "inactive";
  const bool acc3_ok =
      acc3->balance == 300.0 && acc3->status == "active";

  return acc1_ok && acc2_ok && acc3_ok;
}

}  // namespace update_set_operations
```

