```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace full_join_suppliers_products {

struct Supplier {
  sqlgen::PrimaryKey<int> supplier_id;
  std::string name;
};

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int supplier_id;
  std::string name;
};

struct SupProd {
  std::string supplier_name;
  std::optional<std::string> product_name;
};

/**
 * Returns a vector of SupProd structs, where each struct contains the name of a supplier and the
 * name of a product, if any.
 *
 * This demonstrates a FULL JOIN between suppliers and products. Since SQLite does not support
 * FULL OUTER JOIN directly, we emulate it by UNION-ing:
 *
 *  - all suppliers with their matching products (or NULL if none)
 *  - all products that have no matching supplier (supplier_name=NULL, product_name set)
 */
std::vector<SupProd> full_join_suppliers_products() {
  using sqlgen::col;
  using sqlgen::from;
  using sqlgen::select;
  using sqlgen::full_join;

  // Connect to SQLite database "test_db.sqlite"
  sqlgen::sqlite::Database db{"test_db.sqlite"};

  // Tables
  auto suppliers = from<Supplier>();
  auto products = from<Product>();

  // 1) LEFT-style part: all suppliers, matching products (if any)
  auto left_like =
      select(col<&Supplier::name>().as("supplier_name"),
             col<&Product::name>().as("product_name"))
          .from(suppliers.full_join<Product, "p">( // FULL JOIN is available in sqlgen
              col<&Supplier::supplier_id>() == col<&Product::supplier_id>()));

  // 2) RIGHT-only part: products without matching suppliers
  //    supplier_name will be NULL, product_name will be product.name
  auto right_only =
      select(sqlgen::literal<std::optional<std::string>>(std::nullopt)
                 .as("supplier_name"),
             col<&Product::name>().as("product_name"))
          .from(products.full_join<Supplier, "s">(
              col<&Product::supplier_id>() == col<&Supplier::supplier_id>()))
          .where(col<&Supplier::supplier_id>().is_null());

  // 3) FULL OUTER JOIN emulation: union of the two parts
  auto full_query = left_like.union_all(right_only);

  // Execute and read into SupProd
  std::vector<SupProd> result;
  db.read(full_query, result);
  return result;
}

}  // namespace full_join_suppliers_products
