  std::optional<std::string> first_name;
  std::optional<std::string> last_name;
  std::optional<double> salary;
};

struct JoinAnalysis {
  std::vector<JoinResult> inner_join_results;
  std::vector<JoinResult> left_join_results;
  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

namespace detail {

// Helper to map a generic read-result row into JoinResult.
// We keep this flexible by accessing columns by name.
template <typename Row>
JoinResult make_join_result(const Row& row) {
  JoinResult jr;

  // Department name
  if constexpr (rfl::has_field<Row>("department_name")) {
    if (row.department_name) {
      jr.department_name = *row.department_name;
    } else {
      jr.department_name = std::nullopt;
    }
  } else if constexpr (rfl::has_field<Row>("d_department_name")) {
    // In case of aliased or auto‑generated names (defensive).
    jr.department_name = row.d_department_name;
  }

  // First name
  if constexpr (rfl::has_field<Row>("first_name")) {
    if (row.first_name) {
      jr.first_name = *row.first_name;
    } else {
      jr.first_name = std::nullopt;
    }
  }

  // Last name
  if constexpr (rfl::has_field<Row>("last_name")) {
    if (row.last_name) {
      jr.last_name = *row.last_name;
    } else {
      jr.last_name = std::nullopt;
    }
  }

  // Salary
  if constexpr (rfl::has_field<Row>("salary")) {
    if (row.salary) {
      jr.salary = *row.salary;
    } else {
      jr.salary = std::nullopt;
    }
  }

  return jr;
}

}  // namespace detail

/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating SQL tables in "test_db.sqlite", inserting the provided rows, and executing
 * a variety of join queries (INNER, LEFT, RIGHT, FULL) to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees_impl(const std::vector<Department>& depts,
                                               const std::vector<Employee>& emps) {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;
  using namespace sqlgen::transpilation;

  // Connect to the SQLite database "test_db.sqlite".
  // The sqlite backend exposes a connect() that takes a filename.
  auto conn_result = sqlite::connect("test_db.sqlite");
  if (!conn_result) {
    // If connection fails, just return empty analysis.
    return JoinAnalysis{};
  }
  auto conn = conn_result.value();

  // Ensure clean tables: drop if they exist, then create & populate.
  conn.and_then(drop<Department> | if_exists)
      .and_then(drop<Employee> | if_exists);

  write(conn, depts);
  write(conn, emps);

  JoinAnalysis analysis;

  // 1. INNER JOIN: employees with assigned departments.
  // SELECT d.department_name, e.first_name, e.last_name, e.salary
  // FROM Department d
  // INNER JOIN Employee e ON d.department_id = e.department_id;
  {
    using D = Department;
    using E = Employee;

    constexpr auto d = "d"_t;
    constexpr auto e = "e"_t;

    const auto query =
        select("department_name"_c.as< std::optional<std::string> >(),
               "first_name"_c.as< std::optional<std::string> >(),
               "last_name"_c.as< std::optional<std::string> >(),
               "salary"_c.as< std::optional<double> >()) |
        from<D, d>() |
        inner_join<E, e>("d.department_id"_c == "e.department_id"_c);

    auto result = conn.and_then(read(query));
    if (result) {
      for (const auto& row : *result) {
        analysis.inner_join_results.emplace_back(detail::make_join_result(row));
      }
    }
  }

  // 2. LEFT JOIN: include all employees (even without departments).
  // SELECT d.department_name, e.first_name, e.last_name, e.salary
  // FROM Employee e
  // LEFT JOIN Department d ON e.department_id = d.department_id;
  {
    using D = Department;
    using E = Employee;

    constexpr auto d = "d"_t;
    constexpr auto e = "e"_t;

    const auto query =
        select("department_name"_c.as< std::optional<std::string> >(),
               "first_name"_c.as< std::optional<std::string> >(),
               "last_name"_c.as< std::optional<std::string> >(),
               "salary"_c.as< std::optional<double> >()) |
        from<E, e>() |
        left_join<D, d>("e.department_id"_c == "d.department_id"_c);

    auto result = conn.and_then(read(query));
    if (result) {
      for (const auto& row : *result) {
        analysis.left_join_results.emplace_back(detail::make_join_result(row));
      }
    }
  }

  // 3. RIGHT JOIN: include all departments (even without employees).
  // SELECT d.department_name, e.first_name, e.last_name, e.salary
  // FROM Employee e
  // RIGHT JOIN Department d ON e.department_id = d.department_id;
  {
    using D = Department;
    using E = Employee;

    constexpr auto d = "d"_t;
    constexpr auto e = "e"_t;

    const auto base =
        from<E, e>();

    const auto query =
        select("department_name"_c.as< std::optional<std::string> >(),
               "first_name"_c.as< std::optional<std::string> >(),
               "last_name"_c.as< std::optional<std::string> >(),
               "salary"_c.as< std::optional<double> >()) |
        right_join<D, d>(base, "e.department_id"_c == "d.department_id"_c);

    auto result = conn.and_then(read(query));
    if (result) {
      for (const auto& row : *result) {
        analysis.right_join_results.emplace_back(detail::make_join_result(row));
      }
    }
  }

  // 4. FULL JOIN: include all employees and departments.
  // A direct FULL JOIN is used if supported by sqlgen; otherwise, emulate
  // using UNION of LEFT and RIGHT joins. Here we use the provided full_join.
  {
    using D = Department;
    using E = Employee;

    constexpr auto d = "d"_t;
    constexpr auto e = "e"_t;

    const auto base =
        from<E, e>();

    const auto query =
        select("department_name"_c.as< std::optional<std::string> >(),
               "first_name"_c.as< std::optional<std::string> >(),
               "last_name"_c.as< std::optional<std::string> >(),
               "salary"_c.as< std::optional<double> >()) |
        full_join<D, d>(base, "e.department_id"_c == "d.department_id"_c);

    auto result = conn.and_then(read(query));
    if (result) {
      for (const auto& row : *result) {
        analysis.full_join_results.emplace_back(detail::make_join_result(row));
      }
    }
  }

  return analysis;
}

}  // namespace analyze_department_employees

