#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <unordered_map>

namespace update_inventory_stock {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  int stock;
};

bool update_inventory_stock(const std::unordered_map<int, int>& received) {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to SQLite database
  auto conn_res = sqlite::connect("test_db.sqlite");
  if (!conn_res) return false;
  auto conn = conn_res.value();

  // Ensure the Product table exists
  auto create_res = create_table<Product>(conn);
  if (!create_res) return false;

  // Begin a single transaction for all updates
  auto txn_res = begin_transaction(conn);
  if (!txn_res) return false;
  auto txn = txn_res.value();

  // Iterate through the input map and update each product's stock
  for (const auto& [pid, qty] : received) {
    // Build a parameterized UPDATE statement using sqlgen's DSL
    // UPDATE Product SET stock = stock + :qty WHERE product_id = :pid;
    auto update_stmt =
        update<Product>()
            .set("stock"_f = "stock"_f + qty)
            .where("product_id"_f == pid);

    auto exec_res = exec(txn, update_stmt);
    if (!exec_res) {
      // Roll back the transaction on first failure to ensure atomicity
      auto rb = rollback(txn);
      (void)rb;  // ignore rollback failure in return value
      return false;
    }
  }

  // Commit the transaction if all updates succeeded
  auto commit_res = commit(txn);
  return commit_res.has_value();
}

}  // namespace update_inventory_stock
