#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <stdexcept>

namespace weekday_sales_analysis {

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> sale_time;
};

struct WeekdayStats {
  int weekday;         // 0 = Sunday, 1 = Monday, ..., 6 = Saturday (SQLite strftime('%w', ...))
  int total_quantity;  // Sum of quantity for that weekday
};

/**
 * Description: This function analyzes sales data to calculate total quantity sold for each weekday.
 * Returns: std::vector<WeekdayStats>.
 */
std::vector<WeekdayStats> weekday_sales_analysis() {
  using namespace sqlgen;

  // Open SQLite connection to the provided database.
  sqlite::Connection conn("test_db.sqlite");

  // Build a raw SQL query to:
  // 1. Extract weekday from sale_time (SQLite: strftime('%w', sale_time))
  // 2. Aggregate total quantity per weekday
  //
  // Note: SQLite's strftime('%w', ...) returns:
  //   0 = Sunday, 1 = Monday, ..., 6 = Saturday.
  const std::string sql =
      "SELECT CAST(strftime('%w', sale_time) AS INTEGER) AS weekday, "
      "       SUM(quantity) AS total_quantity "
      "FROM Sales "
      "GROUP BY weekday "
      "ORDER BY weekday";

  // Execute the query and read results into a vector of WeekdayStats.
  auto result = conn.read<std::vector<WeekdayStats>>(sql);
  if (!result) {
    throw std::runtime_error(
        std::string("Failed to analyze weekday sales: ") +
        result.error().message());
  }

  return *result;
}

}  // namespace weekday_sales_analysis
