#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <cmath>  // for std::round if needed

namespace project_time_tracking {

struct Project {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
};

struct TimeLog {
  sqlgen::PrimaryKey<int> log_id;
  int project_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> start_time;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> end_time;
};

struct TimeMetrics {
  sqlgen::PrimaryKey<int> project_id;
  std::string name;
  int day;
  int month;
  int year;
  int hour;
  int minute;
  int second;
  double duration_days;
};

/**
 * Description: This function tracks time metrics for each project, including day, month, year, hour, minute, second, and duration in days.
 * Returns: std::vector<TimeMetrics>.
 */
std::vector<TimeMetrics> project_time_tracking() {
  using namespace sqlgen;

  // Connect to the SQLite database "test_db.sqlite"
  sqlite::Database db("test_db.sqlite");

  // Create table representations for Project and TimeLog
  auto project_table = make_table<Project>("Project");
  auto timelog_table = make_table<TimeLog>("TimeLog");

  // Aliases for easier access
  auto& p = project_table;
  auto& t = timelog_table;

  // Build the query using sqlgen operations and SQLite datetime functions.
  //
  // SQLite doesn't have DAY/MONTH/YEAR/HOUR/MINUTE/SECOND or DAYS_BETWEEN,
  // so we use:
  //   strftime('%d', t.start_time)  -> day
  //   strftime('%m', t.start_time)  -> month
  //   strftime('%Y', t.start_time)  -> year
  //   strftime('%H', t.start_time)  -> hour
  //   strftime('%M', t.start_time)  -> minute
  //   strftime('%S', t.start_time)  -> second
  //
  // For days between we do:
  //   (julianday(t.end_time) - julianday(t.start_time)) AS duration_days

  auto day_expr = functions::cast<int>(
      functions::strftime("%d", t(&TimeLog::start_time)));
  auto month_expr = functions::cast<int>(
      functions::strftime("%m", t(&TimeLog::start_time)));
  auto year_expr = functions::cast<int>(
      functions::strftime("%Y", t(&TimeLog::start_time)));
  auto hour_expr = functions::cast<int>(
      functions::strftime("%H", t(&TimeLog::start_time)));
  auto minute_expr = functions::cast<int>(
      functions::strftime("%M", t(&TimeLog::start_time)));
  auto second_expr = functions::cast<int>(
      functions::strftime("%S", t(&TimeLog::start_time)));

  auto duration_days_expr =
      functions::julianday(t(&TimeLog::end_time)) -
      functions::julianday(t(&TimeLog::start_time));

  // SELECT p.project_id, p.name,
  //        day_expr, month_expr, year_expr,
  //        hour_expr, minute_expr, second_expr,
  //        duration_days_expr
  // FROM Project p
  // INNER JOIN TimeLog t ON p.project_id = t.project_id
  //
  // Even though the requirement mentions weekly grouping, the provided
  // reference SQL is row-level. We'll compute temporal components and
  // durations and then let the caller aggregate as needed.

  auto query =
      select(p(&Project::project_id),
             p(&Project::name),
             day_expr,
             month_expr,
             year_expr,
             hour_expr,
             minute_expr,
             second_expr,
             duration_days_expr)
          .from(p)
          .inner_join(t,
                      p(&Project::project_id) == t(&TimeLog::project_id));

  // Execute and map results into TimeMetrics
  std::vector<TimeMetrics> results;
  db.execute(query, [&](int project_id,
                        const std::string& name,
                        int day,
                        int month,
                        int year,
                        int hour,
                        int minute,
                        int second,
                        double duration_days) {
    TimeMetrics metrics{
        sqlgen::PrimaryKey<int>{project_id},
        name,
        day,
        month,
        year,
        hour,
        minute,
        second,
        duration_days};
    results.push_back(std::move(metrics));
  });

  return results;
}

}  // namespace project_time_tracking
