```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace group_by_with_aggregations {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
};

struct Post {
  sqlgen::PrimaryKey<int> post_id;
  int user_id;
  std::string content;
};

struct Stats {
  sqlgen::PrimaryKey<int> user_id;
  std::string name;
  int post_count;
  std::optional<double> avg_length;
};

/**
 * Description: This function retrieves user statistics including post count and average post length.
 * Returns: std::vector<Stats>.
 */
std::vector<Stats> group_by_with_aggregations() {
  // Connect to the SQLite database "test_db.sqlite".
  auto conn = sqlgen::sqlite::Connection::connect("test_db.sqlite");

  // Build a query that:
  // - joins User and Post on user_id
  // - groups by user_id and name
  // - computes COUNT(posts) and AVG(length(content))
  //
  // The target type Stats must match the selected columns in order:
  //   user_id, name, post_count, avg_length.
  auto results =
      sqlgen::select<Stats>()
          .from<User>()
          .join<Post>(sqlgen::on(User{}.user_id == Post{}.user_id))
          .group_by(User{}.user_id, User{}.name)
          .select(
              User{}.user_id,
              User{}.name,
              sqlgen::count(Post{}.post_id),
              sqlgen::avg(sqlgen::length(Post{}.content)))
          .execute(conn);

  return results;
}

}  // namespace group_by_with_aggregations
